package io.knowledgebrain.planning;
import java.util.*;import java.time.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class RecurrenceRulesTest {
 UUID space=new UuidV7(Clock.systemUTC()).next();
 RecurrenceRules.Input input(String a,String z,String frequency,int count,String start,String end){return new RecurrenceRules.Input("Repeated","",a,z,"America/New_York",null,frequency,1,count,start,end);}
 @Test void dailyAndWeeklyUseWallClockCalendarArithmeticAcrossOffsetChanges(){for(String f:List.of("DAILY","WEEKLY")){var p=RecurrenceRules.preview(space,input("2028-03-11T09:00:00","2028-03-11T10:00:00",f,3,"REJECT","REJECT"));assertTrue(p.issues().isEmpty());assertEquals(3,p.occurrences().size());assertEquals("-05:00",p.occurrences().getFirst().startsOffset());assertEquals("-04:00",p.occurrences().getLast().startsOffset());assertTrue(p.occurrences().getLast().startsLocal().endsWith("09:00:00"));assertEquals(p.previewHash(),RecurrenceRules.preview(space,p.input()).previewHash());assertNotEquals(p.previewHash(),RecurrenceRules.preview(new UuidV7(Clock.systemUTC()).next(),p.input()).previewHash());}}
 @Test void gapsAndOverlapsAreExplicitAndNeverSilentlyShifted(){var gap=RecurrenceRules.preview(space,input("2028-03-11T02:30:00","2028-03-11T03:30:00","DAILY",3,"EARLIER","LATER"));assertNull(gap.previewHash());assertTrue(gap.issues().stream().anyMatch(i->i.ordinal()==2&&i.reason().equals("GAP")));var overlap=RecurrenceRules.preview(space,input("2028-11-05T01:30:00","2028-11-05T01:45:00","DAILY",2,"REJECT","REJECT"));assertEquals(2,overlap.issues().size());assertEquals(2,overlap.issues().getFirst().options().size());var explicit=RecurrenceRules.preview(space,input("2028-11-05T01:30:00","2028-11-05T01:45:00","DAILY",2,"EARLIER","LATER"));assertTrue(explicit.issues().isEmpty());assertEquals("2028-11-05T05:30:00Z",explicit.occurrences().getFirst().startsAt());assertEquals("2028-11-05T06:45:00Z",explicit.occurrences().getFirst().endsAt());assertNotEquals(explicit.previewHash(),RecurrenceRules.preview(space,input("2028-11-05T01:30:00","2028-11-05T01:45:00","DAILY",2,"LATER","LATER")).previewHash());}
 @Test void limitsCalendarBoundsAndNonpositiveInstancesAreRejected(){var p=RecurrenceRules.preview(space,input("9999-12-31T12:00:00","9999-12-31T13:00:00","DAILY",2,"REJECT","REJECT"));assertNull(p.previewHash());assertTrue(p.issues().stream().anyMatch(i->i.reason().equals("OUT_OF_RANGE")));var reversed=RecurrenceRules.preview(space,input("2028-01-01T13:00:00","2028-01-01T12:00:00","DAILY",2,"REJECT","REJECT"));assertEquals(2,reversed.issues().size());for(int count:List.of(0,1,101))assertThrows(RuntimeException.class,()->RecurrenceRules.input(input("2028-01-01T12:00:00","2028-01-01T13:00:00","DAILY",count,"REJECT","REJECT")));assertThrows(RuntimeException.class,()->RecurrenceRules.input(input("2028-01-01T12:00:00","2028-01-01T13:00:00","MONTHLY",2,"REJECT","REJECT")));}
}
